using System.Globalization;
using System.Text.Json;
using Index.Domain.Model;
using Xunit;

namespace Index.Tests.Snowball;

/// <summary>
/// Guard G7 (D134): <see cref="SnowballEngine"/> reproduces the Debt Snowball sheet's own "Loans Today"
/// formulas exactly, to the cent and the day.
///
/// <para>The expected table is NOT computed by the engine and NOT copied from the owner's sheet. It is
/// generated by <c>Oracle/sheet_oracle.py</c>, an independent implementation written from the formulas as
/// INDEX-P11-TECHNICAL-FINDING.md Appendix A documents them (it finds the weeks to payoff by exact
/// rational arithmetic, one weekly payment at a time, where the engine takes a logarithm), run over
/// INVENTED inputs of the same shape as the real sheet: ten loans in focus order, the first three already
/// paid off, a mortgage-like loan last, whole-week dates. Its output is committed beside it as
/// <c>sheet_expected.json</c> and embedded, so no Python runs at test time. If this fails, the engine
/// disagrees with the documented formulas; regenerate the table only when the oracle itself was
/// deliberately changed.</para>
///
/// <para>The documented quirks each have a test of their own below, so a regression names the formula it
/// broke rather than just "the table differs": interest before a loan is the focus is a share of the
/// payment (not the balance), the focused payment is cumulative, dates are whole weeks, row 2's
/// E-for-D quirk is harmless because F is 0, <c>H = 0</c> when <c>G = 0</c>, and the focus hands off to the
/// next loan after the previous one's weeks.</para>
/// </summary>
public class SnowballSheetTests
{
    private const string ResourceName = "Index.Tests.Snowball.sheet_expected.json";

    private sealed record ExpectedRow(string Name, decimal E, int F, decimal G, int H, DateOnly I);

    private sealed record Scenario(
        string Title,
        DateOnly LastPaymentDate,
        decimal Extra,
        IReadOnlyList<SnowballLoanInput> Loans,
        IReadOnlyList<ExpectedRow> Rows,
        decimal TotalBalance,
        int TotalWeeks,
        DateOnly DebtFreeDate)
    {
        public IReadOnlyList<SnowballRow> Run() => SnowballEngine.Calculate(Loans, Extra, LastPaymentDate);
    }

    private static readonly Lazy<IReadOnlyList<Scenario>> Loaded = new(Load);

    public static IEnumerable<object[]> ScenarioIndexes() =>
        Enumerable.Range(0, Loaded.Value.Count).Select(i => new object[] { i });

    private static Scenario Get(int index) => Loaded.Value[index];

    private static decimal Money(JsonElement element) =>
        decimal.Parse(element.GetString()!, NumberStyles.Number, CultureInfo.InvariantCulture);

    private static DateOnly Day(JsonElement element) =>
        DateOnly.ParseExact(element.GetString()!, "yyyy-MM-dd", CultureInfo.InvariantCulture);

    private static IReadOnlyList<Scenario> Load()
    {
        using var stream = typeof(SnowballSheetTests).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"{ResourceName} is not embedded in the test assembly.");
        using var document = JsonDocument.Parse(stream);

        var scenarios = new List<Scenario>();
        foreach (var item in document.RootElement.GetProperty("scenarios").EnumerateArray())
        {
            var loans = item.GetProperty("loans").EnumerateArray()
                .Select(l => new SnowballLoanInput(
                    l.GetProperty("name").GetString()!,
                    Money(l.GetProperty("balance")),
                    Money(l.GetProperty("apr")),
                    Money(l.GetProperty("weeklyPayment"))))
                .ToList();
            var rows = item.GetProperty("rows").EnumerateArray()
                .Select(r => new ExpectedRow(
                    r.GetProperty("name").GetString()!,
                    Money(r.GetProperty("e")),
                    r.GetProperty("f").GetInt32(),
                    Money(r.GetProperty("g")),
                    r.GetProperty("h").GetInt32(),
                    Day(r.GetProperty("i"))))
                .ToList();

            scenarios.Add(new Scenario(
                item.GetProperty("title").GetString()!,
                Day(item.GetProperty("lastPaymentDate")),
                Money(item.GetProperty("extraWeeklyPayment")),
                loans,
                rows,
                Money(item.GetProperty("totalBalance")),
                item.GetProperty("totalWeeks").GetInt32(),
                Day(item.GetProperty("debtFreeDate"))));
        }

        return scenarios;
    }

    // ---- the oracle's table is the shape the sheet has ----

    [Fact]
    public void TheOracleTableHasTheShapeOfTheSheet_TenLoansThreePaidOffAndAMortgageLikeLoanLast()
    {
        var sheet = Get(0);

        Assert.Equal(10, sheet.Loans.Count);
        Assert.Equal(0, sheet.Extra);
        Assert.All(sheet.Loans.Take(3), l => Assert.Equal(0m, l.Balance));
        Assert.All(sheet.Loans.Skip(3), l => Assert.True(l.Balance > 0m));

        var last = sheet.Loans[^1];
        Assert.Equal(sheet.Loans.Max(l => l.Balance), last.Balance);
        Assert.True(last.Apr < 0.05m, "the last loan should be mortgage-like: large balance, low rate");
        Assert.True(sheet.Loans.Take(9).All(l => l.Apr != last.Apr));
        Assert.Equal(DayOfWeek.Friday, sheet.LastPaymentDate.DayOfWeek);
    }

    // ---- every column, to the cent and the day ----

    [Theory]
    [MemberData(nameof(ScenarioIndexes))]
    public void ReproducesEveryColumn_ForEveryLoan_ToTheCentAndTheDay(int index)
    {
        var scenario = Get(index);
        var rows = scenario.Run();

        Assert.Equal(scenario.Loans.Count, rows.Count);
        Assert.Equal(scenario.Rows.Count, rows.Count);

        for (var i = 0; i < rows.Count; i++)
        {
            var row = rows[i];
            var expected = scenario.Rows[i];
            var who = $"{scenario.Title} / {expected.Name}";

            Assert.True(expected.Name == row.Name, $"{who}: name {row.Name}");
            Assert.True(expected.E == row.FocusedWeeklyPayment, $"{who}: E expected {expected.E}, got {row.FocusedWeeklyPayment}");
            Assert.True(expected.F == row.WeeksBeforeFocused, $"{who}: F expected {expected.F}, got {row.WeeksBeforeFocused}");
            Assert.True(expected.G == row.AmountBeforeFocused, $"{who}: G expected {expected.G}, got {row.AmountBeforeFocused}");
            Assert.True(expected.H == row.WeeksToPayoff, $"{who}: H expected {expected.H}, got {row.WeeksToPayoff}");
            Assert.True(expected.I == row.PayoffDate, $"{who}: I expected {expected.I}, got {row.PayoffDate}");
        }
    }

    // ---- the documented quirks, one test each ----

    [Theory]
    [MemberData(nameof(ScenarioIndexes))]
    public void TheFocusedPaymentIsCumulative_EachLoansIsThePreviousOnesPlusItsOwn(int index)
    {
        var scenario = Get(index);
        var rows = scenario.Run();

        Assert.Equal(scenario.Loans[0].WeeklyPayment + scenario.Extra, rows[0].FocusedWeeklyPayment);
        for (var i = 1; i < rows.Count; i++)
        {
            Assert.Equal(rows[i - 1].FocusedWeeklyPayment + scenario.Loans[i].WeeklyPayment, rows[i].FocusedWeeklyPayment);
        }

        Assert.Equal(scenario.Loans.Sum(l => l.WeeklyPayment) + scenario.Extra, rows[^1].FocusedWeeklyPayment);
    }

    [Theory]
    [MemberData(nameof(ScenarioIndexes))]
    public void TheFocusHandsOffWhenTheLoanBeforeIsDone_WeeksBeforeFocusedIsTheWeeksSpentSoFar(int index)
    {
        var scenario = Get(index);
        var rows = scenario.Run();

        Assert.Equal(0, rows[0].WeeksBeforeFocused);
        for (var i = 1; i < rows.Count; i++)
        {
            Assert.Equal(rows[i - 1].WeeksBeforeFocused + rows[i - 1].WeeksToPayoff, rows[i].WeeksBeforeFocused);
        }
    }

    [Theory]
    [MemberData(nameof(ScenarioIndexes))]
    public void PayoffDatesAreWholeWeeks_EachIsThePreviousPlusSevenTimesItsWeeks(int index)
    {
        var scenario = Get(index);
        var rows = scenario.Run();

        var previous = scenario.LastPaymentDate;
        foreach (var row in rows)
        {
            Assert.Equal(7 * row.WeeksToPayoff, row.PayoffDate.DayNumber - previous.DayNumber);
            Assert.Equal(0, (row.PayoffDate.DayNumber - scenario.LastPaymentDate.DayNumber) % 7);
            Assert.Equal(scenario.LastPaymentDate.DayOfWeek, row.PayoffDate.DayOfWeek);
            previous = row.PayoffDate;
        }
    }

    [Theory]
    [MemberData(nameof(ScenarioIndexes))]
    public void PayoffOrderingFollowsFocusOrder_DatesNeverGoBackwards(int index)
    {
        var rows = Get(index).Run();

        for (var i = 1; i < rows.Count; i++)
        {
            Assert.True(rows[i].PayoffDate >= rows[i - 1].PayoffDate,
                $"{rows[i].Name} pays off before {rows[i - 1].Name}, which is ahead of it in the focus order");
        }
    }

    [Fact]
    public void APaidOffLoanTakesNoWeeksAndMovesNoDate_HIsZeroWhenGIsZero()
    {
        var sheet = Get(0);
        var rows = sheet.Run();

        for (var i = 0; i < 3; i++)
        {
            Assert.Equal(0m, rows[i].AmountBeforeFocused);
            Assert.Equal(0, rows[i].WeeksToPayoff);
            Assert.Equal(sheet.LastPaymentDate, rows[i].PayoffDate);
        }

        // ...and it adds nothing to the loans after it: their dates start from the anchor, not a week on.
        Assert.Equal(0, rows[3].WeeksBeforeFocused);
        Assert.Equal(sheet.LastPaymentDate.AddDays(7 * rows[3].WeeksToPayoff), rows[3].PayoffDate);
    }

    [Fact]
    public void APaidOffLoanFirstWithAnExtraPayment_StillRollsTheExtraDownAndMovesNoDate()
    {
        var scenario = Get(2);
        var rows = scenario.Run();

        Assert.Equal(0m, scenario.Loans[0].Balance);
        Assert.True(scenario.Extra > 0m);
        Assert.Equal(0, rows[0].WeeksToPayoff);
        Assert.Equal(scenario.LastPaymentDate, rows[0].PayoffDate);
        Assert.Equal(scenario.Loans[0].WeeklyPayment + scenario.Extra, rows[0].FocusedWeeklyPayment);
        Assert.Equal(0, rows[1].WeeksBeforeFocused);
    }

    [Fact]
    public void RowTwoQuirk_TheFirstLoanIsOwedItsFullBalanceWhateverItsFocusedPaymentIs()
    {
        // The sheet's second row multiplies by E where every other row multiplies by D; it is harmless
        // only because F is blank there. With a live first loan and an extra payment E and D differ, and
        // G must still be the whole balance (F = 0), not the balance less anything.
        var scenario = Get(1);
        var rows = scenario.Run();
        var first = scenario.Loans[0];

        Assert.True(first.Balance > 0m);
        Assert.True(rows[0].FocusedWeeklyPayment != first.WeeklyPayment);
        Assert.Equal(0, rows[0].WeeksBeforeFocused);
        Assert.Equal(first.Balance, rows[0].AmountBeforeFocused);
    }

    [Fact]
    public void BeforeALoanIsTheFocusInterestIsAShareOfThePaymentNotOfTheBalance()
    {
        // G = B - D * F * (1 - C): the loan is charged C of each payment, so a higher rate leaves more
        // owing, and the balance's own size never enters the reduction. Checked on the mortgage-like
        // loan, whose 123 weeks waiting is where a balance-based model drifts furthest.
        var sheet = Get(0);
        var rows = sheet.Run();
        var mortgage = sheet.Loans[^1];
        var row = rows[^1];

        Assert.True(row.WeeksBeforeFocused > 100);
        var reduction = mortgage.WeeklyPayment * row.WeeksBeforeFocused * (1m - mortgage.Apr);
        Assert.Equal(Math.Round(mortgage.Balance - reduction, 2, MidpointRounding.AwayFromZero), row.AmountBeforeFocused);
    }

    [Fact]
    public void ThePaymentRatherThanTheFocusedPaymentDrivesTheWaitingPhase()
    {
        // A loan that waits is paid its OWN weekly payment meanwhile (D), not the cumulative one (E).
        var sheet = Get(0);
        var rows = sheet.Run();
        var loan = sheet.Loans[7];
        var row = rows[7];

        Assert.True(row.WeeksBeforeFocused > 0);
        Assert.True(row.FocusedWeeklyPayment > loan.WeeklyPayment);
        var ownPaymentReduction = loan.WeeklyPayment * row.WeeksBeforeFocused * (1m - loan.Apr);
        Assert.Equal(Math.Round(loan.Balance - ownPaymentReduction, 2, MidpointRounding.AwayFromZero), row.AmountBeforeFocused);
    }

    [Fact]
    public void AZeroPercentLoanAmortisesByPlainDivision()
    {
        var scenario = Get(1);
        var rows = scenario.Run();
        var loan = scenario.Loans[1];
        var row = rows[1];

        Assert.Equal(0m, loan.Apr);
        var weeks = (int)Math.Ceiling(row.AmountBeforeFocused / row.FocusedWeeklyPayment);
        Assert.Equal(weeks, row.WeeksToPayoff);
    }

    // ---- the totals row ----

    [Theory]
    [MemberData(nameof(ScenarioIndexes))]
    public void TheDebtFreeDateAndWeeksAreTheLastLoansPayoff_AndTheBalanceTotalsMatch(int index)
    {
        var scenario = Get(index);
        var rows = scenario.Run();
        var last = rows[^1];

        Assert.Equal(scenario.DebtFreeDate, last.PayoffDate);
        Assert.Equal(scenario.TotalWeeks, last.WeeksBeforeFocused + last.WeeksToPayoff);
        Assert.Equal(scenario.TotalWeeks, rows.Sum(r => r.WeeksToPayoff));
        Assert.Equal(scenario.LastPaymentDate.AddDays(7 * scenario.TotalWeeks), scenario.DebtFreeDate);
        Assert.Equal(scenario.TotalBalance, rows.Sum(r => r.Balance));
    }
}
